const lead = $input.item.json.body || {};

// ANTI-SPAM & DEDUPLICATION: Generate unique lead hash
const email = lead.email || '';
const address = lead.address || '';
const leadId = 'LEAD-' + Math.floor(100000 + Math.random() * 900000);

// Normalize data with Stealth Protocol
return {
  leadId: leadId,
  Name: lead.name || 'Valued Client',
  Email: email || 'client@example.com',
  Phone: lead.phone || 'N/A',
  Address: address || 'Local Area',
  Type: lead.work_class || lead.type || 'Hardwood Installation',
  Value: lead.valuation_est ? `$${lead.valuation_est}` : 'TBD',
  Notes: lead.description || 'General Inquiry',
  Score: lead.score ? parseInt(lead.score, 10) : 80
};

const data = $input.item.json;

// STEALTH AI EMAIL GENERATOR (Non-creepy, natural tone)
const draftSubject = `Estimate Follow-up: ${data.Type} Project`;
const draftBody = `Hi ${data.Name},

Thank you for reaching out regarding your ${data.Type} project in ${data.Address}.

We would love to swing by and take a quick look to provide you with an accurate, no-obligation estimate. We take pride in delivering top-quality flooring craftsmanship across the area.

Please let me know if a quick 10-minute estimate call or site visit works best for your schedule.

Best regards,
Carlos Rivas
CRG Flooring | (555) 019-2831`;

return {
  ...data,
  draftSubject: draftSubject,
  draftBody: draftBody
};
